import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import extractText from 'flarum/common/utils/extractText';
import { t } from '../api';
import { Person, Time } from './parts';
/**
 * Under the canvas: the tile you picked and who painted it, the palette,
 * your cooldown and the button that places. On phones it sticks to the
 * bottom of the screen, so painting never needs a scroll.
 */
export default class Dock extends Component {
  view() {
    const page = this.attrs.page;
    const state = page.live.state;
    if (!state) return m("div", {
      className: "MuralDock MuralDock--empty"
    });
    return m("div", {
      className: "MuralDock"
    }, app.session.user ? this.painter(page) : this.guest());
  }
  guest() {
    return m("div", {
      className: "MuralDock-note"
    }, m(Icon, {
      name: "fas fa-paintbrush"
    }), m("span", null, t('dock.guest')), m(Button, {
      className: "Button Button--primary",
      onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
    }, t('dock.log_in')));
  }
  painter(page) {
    const me = page.live.me;
    if (!me) return null;
    if (me.banned) {
      return m("div", {
        className: "MuralDock-note MuralDock-note--warn"
      }, m(Icon, {
        name: "fas fa-ban"
      }), m("span", null, me.banned.until ? t('dock.banned_until', {
        date: new Date(me.banned.until).toLocaleString()
      }) : t('dock.banned')));
    }
    if (!me.confirmed) {
      return m("div", {
        className: "MuralDock-note"
      }, m(Icon, {
        name: "fas fa-envelope"
      }), m("span", null, t('dock.confirm_email')));
    }
    if (!me.canPaint) {
      return m("div", {
        className: "MuralDock-note"
      }, m(Icon, {
        name: "fas fa-lock"
      }), m("span", null, t('dock.no_permission')));
    }
    const palette = page.live.state.season.palette;
    const left = page.live.secondsLeft();
    const ready = left === 0;
    const canPlace = ready && page.selected && page.colour !== null && !page.placing;
    return [this.tileLine(page), m("div", {
      className: "MuralDock-row"
    }, m("div", {
      className: "MuralPalette",
      role: "radiogroup",
      "aria-label": extractText(t('dock.palette'))
    }, palette.map((hex, i) => m("button", {
      type: "button",
      className: classList('MuralPalette-swatch', page.colour === i && 'is-active'),
      style: {
        '--swatch': hex
      },
      role: "radio",
      "aria-checked": page.colour === i ? 'true' : 'false',
      "aria-label": hex,
      title: hex,
      onclick: () => page.pickColour(i)
    }))), m("div", {
      className: "MuralDock-go"
    }, this.ring(left, me.cooldown), m(Button, {
      className: classList('Button Button--primary MuralDock-place', canPlace && 'is-ready'),
      icon: "fas fa-paintbrush",
      disabled: !canPlace,
      loading: page.placing,
      onclick: () => page.place()
    }, ready ? t('dock.place') : t('dock.wait'))))];
  }
  tileLine(page) {
    const tile = page.selected;
    if (!tile) {
      return m("div", {
        className: "MuralDock-tile MuralDock-tile--hint"
      }, m(Icon, {
        name: "fas fa-hand-pointer"
      }), " ", page.colour === null ? t('dock.hint') : t('dock.hint_tile'));
    }
    const info = page.info;
    const palette = page.live.state.season.palette;
    const current = page.viewer?.colourAt(tile[0], tile[1]) ?? 0;
    return m("div", {
      className: "MuralDock-tile"
    }, m("span", {
      className: "MuralSwatch",
      style: {
        background: palette[current]
      }
    }), m("span", {
      className: "MuralDock-where"
    }, t('dock.tile', {
      x: tile[0],
      y: tile[1]
    })), info === undefined ? null : info ? m("span", {
      className: "MuralDock-who"
    }, t('dock.by'), " ", m(Person, {
      row: info.user,
      size: "small"
    }), " \xB7 ", m(Time, {
      at: info.placedAt
    }), info.count > 1 ? m("span", {
      className: "MuralDock-count"
    }, " \xB7 ", t('dock.repainted', {
      count: info.count
    })) : null) : m("span", {
      className: "MuralDock-who"
    }, t('tile.blank')));
  }

  /** The cooldown as a ring that fills back up, with the time in the middle. */
  ring(left, cooldown) {
    const r = 17;
    const c = 2 * Math.PI * r;
    const done = cooldown > 0 ? 1 - Math.min(1, left / cooldown) : 1;
    const mm = Math.floor(left / 60);
    const ss = String(left % 60).padStart(2, '0');
    const label = left === 0 ? extractText(t('dock.ready')) : left >= 3600 ? `${Math.floor(left / 3600)}h${String(Math.floor(left % 3600 / 60)).padStart(2, '0')}` : `${mm}:${ss}`;
    return m("div", {
      className: classList('MuralRing', left === 0 && 'is-ready'),
      role: "timer",
      "aria-live": "off",
      "aria-label": left === 0 ? label : extractText(t('dock.next_in', {
        time: label
      }))
    }, m("svg", {
      viewBox: "0 0 40 40",
      "aria-hidden": "true"
    }, m("circle", {
      className: "MuralRing-track",
      cx: "20",
      cy: "20",
      r: r
    }), m("circle", {
      className: "MuralRing-fill",
      cx: "20",
      cy: "20",
      r: r,
      style: {
        strokeDasharray: `${c}`,
        strokeDashoffset: `${c * (1 - done)}`
      }
    })), m("span", {
      className: "MuralRing-text"
    }, left === 0 ? m(Icon, {
      name: "fas fa-check"
    }) : label));
  }
}
flarum.reg.add('ernestdefoe-mural', 'forum/components/Dock', Dock);